<script setup lang="ts">import { computed,onMounted,ref,watch } from 'vue';import { useRouter } from 'vue-router';import { ArrowUpRight,Plus,MessageCircle,CalendarRange,Brain,Library,Sparkles } from '@lucide/vue';import { useAppStore } from '../stores/app';import { api } from '../services/api';import type { TripVersion } from '../types';import ItineraryPanel from '../components/ItineraryPanel.vue';import EmptyState from '../components/EmptyState.vue';const app=useAppStore(),router=useRouter(),recent=computed(()=>app.sessions.slice(0,4)),activeVersion=ref<TripVersion|null>(null);
/** 创建新会话并进入聊天页面。 */
async function start(){const s=await app.createSession();router.push(`/chat/${s.session_id}`)}
/** 加载当前会话及其最新行程版本，供仪表盘预览。 */
async function loadActive(){if(!app.sessions.length)await app.loadSessions().catch(()=>undefined);if(!app.activeSessionId)return;await app.selectSession(app.activeSessionId);const trip=app.activeTrip;if(trip)activeVersion.value=(await api.tripVersions(trip.trip_id,trip.session_id)).at(-1)||null}onMounted(loadActive);watch(()=>app.activeSessionId,loadActive)</script>
<template><div class="dashboard-grid"><section class="hero-card paper-card"><span class="hero-kicker"><Sparkles :size="15"/> PERSONAL TRAVEL STUDIO</span><h2>下一段旅程，<br><em>从你真正喜欢的方式开始。</em></h2><p>把模糊的想法交给 TravelMind。它会结合实时工具、你的旅行记忆和可信知识，整理出能真正出发的计划。</p><button class="button primary large" @click="start"><Plus :size="18"/>创建新旅程</button><div class="hero-index">08</div></section><ItineraryPanel :itinerary="activeVersion?.itinerary" compact/><section class="paper-card recent-card"><div class="section-heading"><div><span class="eyebrow">RECENT NOTES</span><h2>最近会话</h2></div><RouterLink to="/chat" class="text-link">全部<ArrowUpRight :size="15"/></RouterLink></div><div v-if="recent.length" class="recent-list"><button v-for="session in recent" :key="session.session_id" @click="app.selectSession(session.session_id).then(()=>router.push(`/chat/${session.session_id}`))"><span class="recent-icon"><MessageCircle :size="18"/></span><span><strong>{{session.title||'未命名旅程'}}</strong><small>{{session.current_trip_id?'行程正在规划中':'继续聊聊你的想法'}}</small></span><ArrowUpRight :size="17"/></button></div><EmptyState v-else title="还没有旅行会话" description="创建第一段对话，所有灵感和计划都会留在这里。"/></section><section class="paper-card quick-card"><div class="section-heading"><div><span class="eyebrow">YOUR TRAVEL SYSTEM</span><h2>旅行资产</h2></div></div><div class="quick-grid"><RouterLink to="/trips"><CalendarRange :size="22"/><span><strong>行程册</strong><small>地图、时间轴与版本</small></span></RouterLink><RouterLink to="/memory"><Brain :size="22"/><span><strong>旅行记忆</strong><small>查看系统了解的你</small></span></RouterLink><RouterLink to="/knowledge"><Library :size="22"/><span><strong>私人知识库</strong><small>导入攻略与资料</small></span></RouterLink></div></section></div></template>
